// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    // fuzzed parameters: an address 'from', an address 'caddress' and a uint 'v'
    // We will fuzz the _tos array length by constructing it: we need to test the universal property
    // that the reference contract reverts iff _tos.length == 0. The mutant breaks when _tos.length==0.
    function testFuzz_property(address from, address caddress, uint256 v) public {
        // keep domain wide but avoid the trivial case where caddress is zero (still allowed, but harmless)
        // No tight assumptions so fuzzer can choose length 0 to trigger the difference.

        // Build an empty _tos array to test the universal rule about empty array behavior.
        address[] memory emptyTos = new address[](0);

        // Call and capture whether it reverts.
        bool ok;
        try c.transfer(from, caddress, emptyTos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference C requires _tos.length > 0, so for EVERY input this call must revert (ok==false).
        // The mutant with require(_tos.length >= 0) will not revert (ok==true) for the empty array case,
        // thus violating this universal property. We assert the property that the reference satisfies.
        assertTrue(!ok);
    }
}
